using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalEconomyTests
{
    internal static WorldSession Start(string person="person:nobunaga",bool economy=true)=>new(NewGameWorld.Create(NewGameWorld.Scenario(),[],person,economyPolicy:economy?RegionalEconomy.Policy:null));
    static CommandResult Act(WorldSession s,EconomyAction action,long amount,string id="request:eco")=>s.ManageLocalEconomy(new(new(id),action,amount),s.PlayerControl,s.Revision);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);var r=s.AdvanceTo(at,100000);Assert.True(s.Seconds>0||s.Seconds==at);}}
    [Fact]public void HarvestAssessmentCollectionAndReliefPreservePhysicalRiceAndPrivateWallets()
    {
        var s=Start();Assert.NotNull(s.LocalEconomyView());Assert.Equal(RegionalEconomy.InitialVillage,s.DiagnosticSnapshot().Economy!.Accounts.VillageRice);Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.CollectLevy,1).Code);long harvest=RegionalEconomy.NextHarvest(s.DiagnosticSnapshot(),0);Advance(s,harvest);var a=s.DiagnosticSnapshot().Economy!.Accounts;Assert.Equal(1000,a.Harvested);Assert.Equal(300,a.Assessed);Assert.Equal(1800,a.VillageRice);
        Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.CollectLevy,300).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.CollectLevy,1,"request:twice").Code);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,200,"request:relief").Code);a=s.DiagnosticSnapshot().Economy!.Accounts;Assert.Equal(1700,a.VillageRice);Assert.Equal(400,a.HouseRice);Assert.Equal(RegionalEconomy.InitialHouse+RegionalEconomy.InitialVillage+a.Harvested,a.VillageRice+a.HouseRice+a.WorksSpent);Assert.Empty(s.DiagnosticSnapshot().Transfers);
    }
    [Fact]public void WorksCostActualRiceWaitSevenDaysThenImproveLaterHarvest()
    {
        var s=Start();Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.ImproveWater,200).Code);Assert.Equal(100,s.DiagnosticSnapshot().Economy!.Accounts.HouseRice);Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.ImproveWater,200,"request:double-work").Code);Advance(s,RegionalEconomy.WorksSeconds-1);Assert.Equal(100,s.DiagnosticSnapshot().Economy!.Accounts.Water);Advance(s,RegionalEconomy.WorksSeconds);Assert.Equal(110,s.DiagnosticSnapshot().Economy!.Accounts.Water);Advance(s,RegionalEconomy.NextHarvest(s.DiagnosticSnapshot(),s.Seconds));Assert.Equal(1100,s.DiagnosticSnapshot().Economy!.Accounts.Harvested);
    }
    [Theory][InlineData(EconomyAction.RelieveVillage,301)][InlineData(EconomyAction.RelieveVillage,0)][InlineData(EconomyAction.CollectLevy,-1)][InlineData(EconomyAction.ImproveWater,199)]
    public void InvalidOrUnfundedActionLeavesWorldUnchanged(EconomyAction action,long amount){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,action,amount).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void IdempotencyAndRevisionAreChecked(){var s=Start();Assert.Equal(ResultCode.StateChanged,s.ManageLocalEconomy(new(new("request:eco"),EconomyAction.RelieveVillage,10),s.PlayerControl,999).Code);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,10).Code);long rev=s.Revision;Assert.Equal(ResultCode.AlreadyAccepted,Act(s,EconomyAction.RelieveVillage,10).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,EconomyAction.RelieveVillage,11).Code);Assert.Equal(rev,s.Revision);}
    [Fact]public void OtherHouseOrWrongActorCannotReadOrSpendLocalAccounts(){var s=Start("person:shingen");Assert.Null(s.LocalEconomyView());Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.RelieveVillage,10).Code);var own=Start();Assert.Equal(ResultCode.NotAvailable,own.ManageLocalEconomy(new(new("request:foreign"),EconomyAction.RelieveVillage,10),new("person:shingen"),own.Revision).Code);Assert.Null(RegionalEconomy.View(own.DiagnosticSnapshot(),new("person:shingen")));}
    [Fact]public void MissingOrTamperedAmountsEventsAndAuthorityAreRejected(){var s=Start();Act(s,EconomyAction.RelieveVillage,10);var w=s.DiagnosticSnapshot();w.Economy=w.Economy! with{Accounts=w.Economy.Accounts with{HouseRice=999}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Economy=w.Economy! with{Events=[new("harvest",0,999,100)]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Economy=w.Economy! with{Orders=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void SameSeedAndDifferentAdvanceChunksHaveIdenticalAccounts(){var a=Start();var b=Start();long at=RegionalEconomy.NextHarvest(a.DiagnosticSnapshot(),0);Advance(a,at);Advance(b,RegionalEconomy.WorksSeconds);Advance(b,at);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Economy),ContractJson.Write(b.DiagnosticSnapshot().Economy));}
    [Fact]public void JsonRecoveryDuringWorkProducesSameFutureWorld(){var a=Start();Act(a,EconomyAction.ImproveWater,200);Advance(a,123);var b=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(a.DiagnosticSnapshot())));long at=RegionalEconomy.NextHarvest(a.DiagnosticSnapshot(),a.Seconds);Advance(a,at);Advance(b,at);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void NullPolicyKeepsOldWorldBytesAndRejectsInjection(){var s=Start(economy:false);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Economy",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.RelieveVillage,1).Code);var w=s.DiagnosticSnapshot();w.Economy=Start().DiagnosticSnapshot().Economy;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void SeasonalBoundaryIsNotSkippedAndNotRepeated(){var s=Start();long at=RegionalEconomy.NextHarvest(s.DiagnosticSnapshot(),0);Advance(s,at-1);Assert.Empty(s.DiagnosticSnapshot().Economy!.Events);Advance(s,at);Assert.Single(s.DiagnosticSnapshot().Economy!.Events);s.SetPaused(true);s.SetPaused(false);Assert.Single(s.DiagnosticSnapshot().Economy!.Events);}

    [Fact]public void ActualGenerationSaveDuringWorkAndAfterCollectionContinuesExactly()
    {
        var a=Start();Assert.Equal(ResultCode.Accepted,Act(a,EconomyAction.ImproveWater,200).Code);Advance(a,123);a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"regional-economy-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"work",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("work"),host.Current,host.Current.Revision));var b=host.Current;ExportEconomy(a,b,"work");long harvest=RegionalEconomy.NextHarvest(w,w.ElapsedSeconds);Advance(a,harvest);Advance(b,harvest);Act(a,EconomyAction.CollectLevy,330,"request:levy");Act(b,EconomyAction.CollectLevy,330,"request:levy");Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.LocalEconomyView()),ContractJson.Write(b.LocalEconomyView()));a.SetPaused(true);Assert.True(store.Save(a,"collected",w.WorldId).Published);var h=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("collected"),h.Current,h.Current.Revision));Assert.Equal(ContractJson.Write(a.LocalEconomyView()),ContractJson.Write(h.Current.LocalEconomyView()));ExportEconomy(a,h.Current,"collected");
    }
    [Fact]public void ProfilePersistsExplicitPolicyAndOldProfileRemainsNull()
    {
        var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"economy-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(),[],"person:nobunaga",42,economyPolicy:RegionalEconomy.Policy);Assert.Equal(RegionalEconomy.Policy,store.Read(p.Instance).EconomyPolicy);Assert.NotNull(NewCampaignStore.Build(p).Economy);var old=store.New(NewGameWorld.Scenario(),[],"person:nobunaga",42);Assert.Null(store.Read(old.Instance).EconomyPolicy);Assert.Null(NewCampaignStore.Build(old).Economy);
    }
    [Fact]public void ActualRoadDepartureHidesAccountsAndBlocksRemoteSpendingThenReturnRestoresView()
    {
        var s=Start();Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,1).Code);var move=TravelWorld.Move(s.DiagnosticSnapshot(),"request:away","sakai");Assert.Equal(ResultCode.Accepted,s.Submit(move,s.Revision).Code);Advance(s,2);Assert.Null(s.LocalEconomyView());Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.RelieveVillage,1,"request:remote").Code);var end=s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt;Advance(s,end);Assert.Null(s.LocalEconomyView());Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:return","castle"),s.Revision).Code);Advance(s,s.Seconds+1);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);Assert.NotNull(s.LocalEconomyView());Assert.Equal(801,s.LocalEconomyView()!.Accounts.VillageRice);
    }
    [Fact]public void EconomicIdCannotAlsoBeACommonTravelIntent()
    {
        var s=Start();Act(s,EconomyAction.RelieveVillage,1);var move=TravelWorld.Move(s.DiagnosticSnapshot(),"request:eco","sakai");Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(move,s.Revision).Code);
    }
    [Fact]public void WaterCompletionAtHarvestOccursOnceBeforeYieldAndWorkReservationsRemainConserved()
    {
        var s=Start();long at=RegionalEconomy.NextHarvest(s.DiagnosticSnapshot(),0);Advance(s,at-RegionalEconomy.WorksSeconds);Act(s,EconomyAction.ImproveWater,200);Advance(s,at);var e=s.DiagnosticSnapshot().Economy!;Assert.Equal(new[]{"water-complete","harvest"},e.Events.Select(x=>x.Kind));Assert.Equal(1100,e.Accounts.Harvested);Assert.Equal(RegionalEconomy.InitialVillage+RegionalEconomy.InitialHouse+e.Accounts.Harvested,e.Accounts.VillageRice+e.Accounts.HouseRice+e.Accounts.WorksSpent);
    }

    static void ExportEconomy(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_ECONOMY_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var row in new[]{(Session:a,Tag:"before"),(Session:b,Tag:"restored")}){File.WriteAllBytes(Path.Combine(dir,name+"."+row.Tag+".json"),ContractJson.Write(row.Session.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,name+"."+row.Tag+".view.json"),ContractJson.Write(row.Session.LocalEconomyView()));}}
    [Fact]public void NormalEntryPoliciesKeepHouseRiceSeparateFromPrivateMonAndPreserveLegacyMilitaryStock()
    {
        var setup=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var s=new WorldSession(NewGameWorld.Create(setup,[],"person:nobunaga",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,RegionalEconomy.Policy));var before=s.DiagnosticSnapshot();long balance=NewGameWork.Balance(before,s.PlayerControl);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,20).Code);Assert.Equal(balance,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));Assert.Empty(s.DiagnosticSnapshot().Transfers);Assert.Equal(320,s.LocalEconomyView()!.Accounts.Relief+300);
    }
}
